use Toolkit\DocGen\DocGenException;
use Toolkit\DocGen\Filesystem\SiteFileWriter;
use Toolkit\DocGen\Render\Social\SocialCard;

/**
 * Publishes the static stylesheet and script assets into the site.
 */
final class AssetPublisher
{
    /** @readonly */
    private SiteFileWriter $writer;

    /** @readonly */
    private SocialCard $card;

    /**
     * Creates an asset publisher.
     */
    public function __construct(?SiteFileWriter $writer = null, ?SocialCard $card = null)
    {
        $this->writer = $writer ?? new SiteFileWriter();
        $this->card = $card ?? new SocialCard();
    }

    /**
     * Publishes all bundled assets and the GitHub Pages marker file.
     *
     * @throws DocGenException when a bundled asset is missing
     */
    public function publish(string $outputRoot): void
    {
        foreach (['style.css', 'app.js'] as $asset) {
            $this->writer->write($outputRoot, 'assets/' . $asset, $this->assetContents($asset));
        }

        $this->writer->write($outputRoot, '.nojekyll', '');
    }

    /**
     * Draws the image a link to the site is previewed with, if it is asked for.
     *
     * A site that does not say where it is published cannot be linked to
     * absolutely, so nothing previews it and nothing is drawn. Neither is
     * anything drawn where the gd extension is missing: the pages then
     * carry no image tag either, and the card is a card without a picture
     * rather than one pointing at a missing file.
     *
     * @param ?string $baseUrl the address the site is published at, if it is known
     * @param string $title the site title, printed as the headline of the card
     * @param string $description what the documented project is, printed below it
     *
     * @throws DocGenException when the image cannot be drawn or written
     */
    public function publishCard(string $outputRoot, ?string $baseUrl, string $title, string $description): void
    {
        if ($baseUrl === null || !$this->card->supported()) {
            return;
        }

        $this->writer->write($outputRoot, SocialCard::PATH, $this->card->render($title, $description));
    }

    /**
     * Reads one bundled asset from the toolkit resources.
     *
     * @throws DocGenException when the asset file is missing or unreadable
     */
    public function assetContents(string $asset): string
    {
        $path = __DIR__ . '/../../../resources/docgen/' . $asset;
        if (!is_file($path)) {
            throw new DocGenException(sprintf('Bundled asset not found: %s', $path));
        }

        $contents = file_get_contents($path);
        if ($contents === false) {
            throw new DocGenException(sprintf('Bundled asset is not readable: %s', $path));
        }

        return $contents;
    }
}
/*
 * DocGen design system.
 *
 * Colors are declared in two layers. The first layer holds the raw palette
 * (--p-*): one accessible value per hue for light and for dark. The second
 * layer maps those hues to roles (--kind-*, --state-*, --syn-*). Nothing
 * outside the palette block may declare a raw color, so a hue is defined
 * once and every role that shares it does so on purpose.
 *
 * Hue budget: blue, violet, amber, teal, pink and indigo carry identity
 * (symbol kinds and layers); green, yellow and red carry state (coverage,
 * warnings, throws); slate carries structure. Syntax highlighting reuses
 * identity hues at text weight only, and never red, so the one red on a
 * page always means "failure state".
 */

:root {
  /* palette — light */
  --p-bg: #ffffff;
  --p-bg-sunken: #f6f8fa;
  --p-bg-raised: #ffffff;
  --p-bg-hover: #eef1f5;
  --p-border: #d8dee4;
  --p-border-muted: #e6eaef;
  --p-fg: #1f2328;
  --p-fg-muted: #59636e;
  --p-fg-subtle: #818b98;

  --p-blue: #0969da;
  --p-violet: #8250df;
  --p-amber: #9a6700;
  --p-teal: #106b70;
  --p-pink: #bf3989;
  --p-indigo: #4649c8;
  --p-green: #1a7f37;
  --p-yellow: #7d4e00;
  --p-red: #cf222e;
  --p-slate: #4c5561;

  /* palette — tints used for chip backgrounds */
  --p-blue-tint: #ddf0ff;
  --p-violet-tint: #f0e7ff;
  --p-amber-tint: #fff3d4;
  --p-teal-tint: #d6f4f2;
  --p-pink-tint: #ffe8f4;
  --p-indigo-tint: #e6e6ff;
  --p-green-tint: #dbfbe3;
  --p-yellow-tint: #fff2cc;
  --p-red-tint: #ffe3e3;
  --p-slate-tint: #eceff3;

  /* roles — symbol identity */
  --kind-class: var(--p-blue);
  --kind-class-tint: var(--p-blue-tint);
  --kind-interface: var(--p-violet);
  --kind-interface-tint: var(--p-violet-tint);
  --kind-trait: var(--p-amber);
  --kind-trait-tint: var(--p-amber-tint);
  --kind-enum: var(--p-teal);
  --kind-enum-tint: var(--p-teal-tint);
  --kind-function: var(--p-pink);
  --kind-function-tint: var(--p-pink-tint);
  --kind-namespace: var(--p-slate);
  --kind-namespace-tint: var(--p-slate-tint);
  --kind-package: var(--p-teal);
  --kind-package-tint: var(--p-teal-tint);
  --kind-layer: var(--p-indigo);
  --kind-layer-tint: var(--p-indigo-tint);

  /* roles — state */
  --state-ok: var(--p-green);
  --state-ok-tint: var(--p-green-tint);
  --state-warn: var(--p-yellow);
  --state-warn-tint: var(--p-yellow-tint);
  --state-danger: var(--p-red);
  --state-danger-tint: var(--p-red-tint);
  --state-test: var(--p-violet);
  --state-test-tint: var(--p-violet-tint);
  --state-neutral: var(--p-fg-muted);
  --state-neutral-tint: var(--p-slate-tint);

  /* roles — diff, on the state hues only: green adds, red removes, yellow
     changes. Identity hues stay with the symbols they belong to, so a mark
     is never read as a kind. */
  --diff-added: var(--p-green);
  --diff-added-tint: var(--p-green-tint);
  --diff-removed: var(--p-red);
  --diff-removed-tint: var(--p-red-tint);
  --diff-modified: var(--p-yellow);
  --diff-modified-tint: var(--p-yellow-tint);

  /* roles — syntax, text weight only */
  --syn-kw: var(--p-violet);
  --syn-str: var(--p-teal);
  --syn-num: var(--p-blue);
  --syn-com: var(--p-fg-subtle);
  --syn-var: var(--p-amber);
  --syn-id: var(--p-fg);

  /* roles — surfaces */
  --bg: var(--p-bg);
  --bg-sunken: var(--p-bg-sunken);
  --bg-raised: var(--p-bg-raised);
  --bg-hover: var(--p-bg-hover);
  --border: var(--p-border);
  --border-muted: var(--p-border-muted);
  --fg: var(--p-fg);
  --fg-muted: var(--p-fg-muted);
  --fg-subtle: var(--p-fg-subtle);
  --link: var(--p-blue);

  /* spacing and type scale */
  --sp-1: 2px;
  --sp-2: 4px;
  --sp-3: 8px;
  --sp-4: 12px;
  --sp-5: 18px;
  --sp-6: 28px;
  --text-xs: 11px;
  --text-sm: 12px;
  --text-md: 13px;
  --text-lg: 14px;
  --radius: 6px;
  --radius-sm: 4px;
}

